{
  "contract": "ReservaX",
  "closure": {
    "site_function": "withdraw",
    "site_call": ".call",
    "functions": [
      "withdraw",
      "earlyPurchase",
      "publicPurchase",
      "setWindows",
      "setMaxEarly",
      "setMaxPublic",
      "setMaxSupply",
      "pauseContract",
      "newCost",
      "setLevels",
      "setAmounts",
      "setAddresses",
      "setCreators"
    ],
    "justification": "These functions can potentially interact with the exposed storage variables during the callback."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "earlyPurchase",
      "publicPurchase",
      "setWindows",
      "setMaxEarly",
      "setMaxPublic",
      "setMaxSupply",
      "pauseContract",
      "newCost",
      "setLevels",
      "setAmounts",
      "setAddresses",
      "setCreators"
    ],
    "nesting_bound": {
      "withdraw": 1
    }
  },
  "phases": {
    "function": "withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlightNine",
      "sol_type": "uint256",
      "meaning": "Amount in transit for token 9 during callback",
      "backed_by_storage": false
    },
    {
      "name": "inFlightTen",
      "sol_type": "uint256",
      "meaning": "Amount in transit for token 10 during callback",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "withdrawNine + inFlightNine <= _totalSupply[9] && withdrawTen + inFlightTen <= _totalSupply[10]",
    "stable_formula": "withdrawNine <= _totalSupply[9] && withdrawTen <= _totalSupply[10]",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "withdrawNine <= _totalSupply[9] && withdrawTen <= _totalSupply[10]",
    "rule": "The exposure invariant ensures that the withdrawals do not exceed the total supply during the callback."
  }
}
